mapper.select:
WITH RECURSIVE ics_tree( ics01_class_tree_id , ics01_company_id , ics01_class_tree_nm , ics01_parent_tree_id , ics01_seq , ics01_class_tree_cd , ics01_type_cd , ics01_use_yn , depth , path , cycle ) AS ( SELECT ics01_class_tree_id , ics01_company_id , ics01_class_tree_nm , ics01_parent_tree_id , ics01_seq , ics01_class_tree_cd , ics01_type_cd , ics01_use_yn , 1 , ARRAY[CAST(a.ics01_parent_tree_id AS varchar) || LPAD(CAST(a.ics01_seq AS varchar),10,'0')||a.ics01_class_tree_cd||LPAD(CAST(a.ics01_class_tree_id AS varchar),15,'0')] , false FROM ics01_class_tree a WHERE ics01_parent_tree_id = 0 AND ics01_use_yn = 'true'
AND ics01_type_cd LIKE #{typeCode}
UNION ALL SELECT a.ics01_class_tree_id , a.ics01_company_id , a.ics01_class_tree_nm , a.ics01_parent_tree_id , a.ics01_seq , a.ics01_class_tree_cd , a.ics01_type_cd , a.ics01_use_yn , b.depth + 1 , array_append(b.path, CAST(a.ics01_parent_tree_id AS varchar) || LPAD(CAST(a.ics01_seq AS varchar),10,'0')||a.ics01_class_tree_cd||LPAD(CAST(a.ics01_class_tree_id AS varchar),15,'0')) , a.ics01_class_tree_nm = any(b.path) FROM ics01_class_tree a INNER JOIN ics_tree b ON a.ics01_parent_tree_id = b.ics01_class_tree_id WHERE a.ics01_use_yn = 'true'
AND a.ics01_type_cd LIKE #{typeCode}
AND NOT cycle ) SELECT a.ics01_class_tree_id AS class_tree_id, a.ics01_parent_tree_id AS parent_tree_id, a.ics01_class_tree_cd AS class_tree_code, a.ics01_class_tree_nm AS class_tree_name, a.ics01_seq AS seq, ( SELECT MAX(f_get_deadline_nm(sch03_deadline_id,'2')) || CASE WHEN COUNT(*) = 1 THEN '' ELSE ' 외 '||COUNT(*)-1||'건' END FROM sch03_deadline WHERE sch03_info_id = a.ics01_class_tree_id ) AS deadline_full_name, a.depth AS depth FROM ics_tree a ORDER BY path

mapper.update:
UPDATE ics01_class_tree
   SET ics01_class_tree_cd = #{req.classTreeCode},
       ics01_class_tree_nm = #{req.classTreeName},
       ics01_seq           = #{req.seq}
 WHERE ics01_class_tree_id = #{classTreeId}

UPDATE ics01_class_tree
   SET ics01_parent_tree_id = #{parentTreeId}
 WHERE ics01_class_tree_id = #{classTreeId}

mapper.select:
SELECT ics01_class_tree_id AS class_tree_id, ics01_class_tree_cd AS class_tree_code, ics01_class_tree_nm AS class_tree_name, ics01_content AS content, ics01_submit_to AS submit_to, ics01_related_law AS related_law, f_ics_class_tree_nm_allpath(ics01_class_tree_id) AS class_tree_full_name
FROM ics01_class_tree LEFT OUTER JOIN ics03_company_info ON (ics03_ics_class_tree_id = ics01_class_tree_id AND ics03_company_id = #{companyId}) WHERE 1=1
ORDER BY ics01_class_tree_cd LIMIT #{limit} OFFSET #{offset}
